#!/usr/bin/env bash
# Generated by kubegen from examples/aks.yaml - re-generate instead of editing.
# Creates the aks cluster "prod-aks".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need az https://learn.microsoft.com/cli/azure/install-azure-cli
need kubectl https://kubernetes.io/docs/tasks/tools/
[ "$missing" -eq 0 ] || exit 127

KUBECONFIG_OUT="$HOME"/.kube/prod-aks.yaml

echo '==> Checking Azure login'
az account show >/dev/null 2>&1 || die "not logged in to Azure; run: az login"

echo '==> Creating resource group rg-prod-aks'
az group create --name rg-prod-aks --location eastus --output none

echo '==> Creating AKS cluster prod-aks (this takes several minutes)'
az aks create \
  --resource-group rg-prod-aks --name prod-aks --location eastus \
  --kubernetes-version 1.33 \
  --tier standard \
  --nodepool-name system --node-count 3 --node-vm-size Standard_D4s_v5 \
  --zones 1 2 3 \
  --network-plugin azure \
  --network-plugin-mode overlay \
  --network-policy cilium \
  --network-dataplane=cilium \
  --pod-cidr 10.244.0.0/16 \
  --enable-managed-identity \
  --enable-oidc-issuer \
  --enable-workload-identity \
  --generate-ssh-keys \
  --tags env=prod 'owner=platform team' \
  --output none

echo '==> Adding node pool apps'
az aks nodepool add \
  --resource-group rg-prod-aks --cluster-name prod-aks --name apps --mode User \
  --node-count 2 --node-vm-size Standard_D8s_v5 \
  --node-osdisk-size 128 \
  --enable-cluster-autoscaler --min-count 2 --max-count 10 \
  --labels workload=apps \
  --output none

echo '==> Adding node pool batch'
az aks nodepool add \
  --resource-group rg-prod-aks --cluster-name prod-aks --name batch --mode User \
  --node-count 0 --node-vm-size Standard_D8s_v5 \
  --enable-cluster-autoscaler --min-count 0 --max-count 20 \
  --node-taints workload=batch:NoSchedule \
  --priority Spot --eviction-policy Delete --spot-max-price -1 \
  --output none

echo '==> Fetching credentials'
az aks get-credentials --resource-group rg-prod-aks --name prod-aks --overwrite-existing \
  --file "$KUBECONFIG_OUT"

echo '==> Verifying access to prod-aks'
kubectl --kubeconfig "$KUBECONFIG_OUT" get nodes -o wide

echo "Cluster prod-aks is ready. Kubeconfig: $KUBECONFIG_OUT"
